437\\u0430\\u0433\\u043b\\u0443\\u0448\\u0451\\u043d\\u043d\\u044b\\u0439 \\u0431\\u043e\\u043b\\u044c\\u0448\\u0438\\u043c (\\u0435\\u0441\\u043b\\u0438 env \\u043f\\u043e\\u0437\\u0432\\u043e\\u043b\\u044f\\u0435\\u0442 \\u0437\\u0430\\u0434\\u0430\\u0442\\u044c horizon \\u2014 \\u0441\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043f\\u043e \\u043a\\u043e\\u0434\\u0443), \\u0431\\u0435\\u0437 \\u0440\\u0435\\u0441\\u0435\\u0442\\u043e\\u0432 \\u0432 \\u043e\\u043a\\u043d\\u0435 \\u0437\\u0430\\u043c\\u0435\\u0440\\u0430; \\u0440\\u0430\\u0437\\u043d\\u0438\\u0446\\u0430 \\u043f\\u043e \\u0440\\u0443\\u043a\\u0430\\u043c = \\u0432\\u043a\\u043b\\u0430\\u0434 autoreset \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0440\\u043e\\u043a\\u043e\\u0439. \\u0415\\u0441\\u043b\\u0438 \\u0437\\u0430\\u0433\\u043b\\u0443\\u0448\\u0438\\u0442\\u044c \\u043d\\u0435\\u043b\\u044c\\u0437\\u044f \\u2014 \\u0441\\u0442\\u0440\\u043e\\u043a\\u0430 \\u00ab\\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u043d\\u043e\\u0435 \\u0441\\u043c\\u0435\\u0449\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0430\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f: A \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u0442 autoreset \\u0432 step-\\u0432\\u0440\\u0435\\u043c\\u044f, B \\u043d\\u0435 \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u0442 reset \\u0432\\u043e\\u0432\\u0441\\u0435\\u00bb. \\u042d\\u043a\\u0441\\u043f\\u043e\\u0440\\u0442/\\u0440\\u0435\\u043d\\u0434\\u0435\\u0440/\\u043f\\u0430\\u0440\\u0441\\u0438\\u043d\\u0433/\\u0441\\u043e\\u0437\\u0434\\u0430\\u043d\\u0438\\u0435 env/import \\u2014 \\u0432\\u043d\\u0435 \\u0432\\u0441\\u0435\\u0445 \\u0442\\u0430\\u0439\\u043c\\u0435\\u0440\\u043e\\u0432.\\n\\n## (\\u0434) \\u0410\\u043d\\u0430\\u043b\\u0438\\u0437\\n\\n- \\u041f\\u043e \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0435: **\\u043c\\u0435\\u0434\\u0438\\u0430\\u043d\\u0430 + IQR \\u043f\\u043e 7 \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440\\u0430\\u043c** (\\u043d\\u0435 \\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u0435); \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u043e \\u043e\\u0442\\u0431\\u0440\\u0430\\u043a\\u043e\\u0432\\u043a\\u0438: \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440 \\u0441 loadavg-\\u0430\\u043d\\u043e\\u043c\\u0430\\u043b\\u0438\\u0435\\u0439 \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u0442\\u0441\\u044f \\u0438 \\u0434\\u043e\\u0431\\u0438\\u0440\\u0430\\u0435\\u0442\\u0441\\u044f.\\n- **Per-core \\u043d\\u043e\\u0440\\u043c\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f**: steps/sec \\u00f7 \\u0438\\u0437\\u043c\\u0435\\u0440\\u0435\\u043d\\u043d\\u044b\\u0435 \\u044f\\u0434\\u0440\\u0430 \\u2014 \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445 A/B1/B2.\\n- **\\u041a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0439 \\u043f\\u043b\\u0430\\u0442\\u043e** \\u043f\\u043e n_envs: \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 < 10% \\u043f\\u0440\\u0438 \\u0443\\u0434\\u0432\\u043e\\u0435\\u043d\\u0438\\u0438 \\u2192 \\u043f\\u043b\\u0430\\u0442\\u043e; \\u0442\\u043e\\u0447\\u043a\\u0430 \\u043f\\u043e\\u043b\\u0443\\u043f\\u043b\\u0430\\u0442\\u043e (\\u043f\\u0435\\u0440\\u0432\\u044b\\u0439 n_envs \\u0441 \\u226550% \\u043d\\u0430\\u043a\\u043b\\u043e\\u043da asymptote) \\u043a\\u0430\\u043a \\u043e\\u043f\\u0438\\u0441\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u0430\\u044f \\u0445\\u0430\\u0440\\u0430\\u043a\\u0442\\u0435\\u0440\\u0438\\u0441\\u0442\\u0438\\u043a\\u0430.\\n- **\\u041e\\u0442\\u0432\\u0435\\u0442 \\u043d\\u0430 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441** = \\u0434\\u0432\\u0430 \\u0447\\u0438\\u0441\\u043b\\u0430: (1) \\u043e\\u0442\\u043d\\u043e\\u0448\\u0435\\u043d\\u0438\\u0435 A(mt=K)/B2(K) **\\u043f\\u0440\\u0438 \\u0440\\u0430\\u0432\\u043d\\u043e\\u043c \\u0447\\u0438\\u0441\\u043b\\u0435 \\u044f\\u0434\\u0435\\u0440**, \\u043f\\u043e \\u0442\\u0440\\u0451\\u043c \\u043c\\u0435\\u