n| n_landmarks | 2 | \\u0438\\u0437 \\u043b\\u0438\\u0442\\u0435\\u0440\\u0430\\u0442\\u0443\\u0440\\u044b, \\u0441\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043f\\u043e \\u043a\\u043e\\u0434\\u0443 |\\n| obs_dim | 18 | \\u0432\\u044b\\u0432\\u043e\\u0434 \\u0438\\u0437 \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u043e\\u0432, \\u0441\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c |\\n| act_dim | 5, **\\u0434\\u0438\\u0441\\u043a\\u0440\\u0435\\u0442\\u043d\\u043e\\u0435** (`discrete_action_space=True` \\u043f\\u043e \\u0443\\u043c\\u043e\\u043b\\u0447\\u0430\\u043d\\u0438\\u044e) | **\\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435 \\u0438\\u0437 \\u0432\\u043d\\u0435\\u0448\\u043d\\u0438\\u0445 \\u0437\\u043d\\u0430\\u043d\\u0438\\u0439, \\u041d\\u0415 \\u0444\\u0430\\u043a\\u0442; \\u0441\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043f\\u043e `mpe_env.py`/\\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0430\\u043c \\u043f\\u0440\\u0438 \\u043f\\u043e\\u044f\\u0432\\u043b\\u0435\\u043d\\u0438\\u0438 \\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u0438\\u043a\\u043e\\u0432** |\\n| max_episode_steps | 100 (\\u0448\\u0442\\u0430\\u0442\\u043d\\u044b\\u0439) + \\u0441\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u0439 H=\\u0431\\u043e\\u043b\\u044c\\u0448\\u043e\\u0439 (\\u0441\\u043c. \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b) | \\u0438\\u0437 \\u043b\\u0438\\u0442\\u0435\\u0440\\u0430\\u0442\\u0443\\u0440\\u044b, \\u0441\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c |\\n| Random actions | \\u0440\\u0430\\u0432\\u043d\\u043e\\u043c\\u0435\\u0440\\u043d\\u044b\\u0435 \\u043f\\u043e {0..4}: `jax.random.randint` (A) / `np.random.default_rng().integers` (B); \\u0437\\u0435\\u0440na \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u044b | \\u0435\\u0441\\u043b\\u0438 \\u043e\\u043a\\u0430\\u0436\\u0435\\u0442\\u0441\\u044f continuous \\u2014 \\u0437\\u0430\\u043c\\u0435\\u043d\\u044f\\u0435\\u043c \\u043d\\u0430 uniform[\\u22121,1], \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u043d\\u0435 \\u043c\\u0435\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f |\\n\\n\\u041f\\u0430\\u043c\\u044f\\u0442\\u044c \\u043f\\u0440\\u0438 n_envs=1024: \\u0441\\u043e\\u0441\\u0442\\u043e\\u044f\\u043d\\u0438\\u044f \\u043f\\u043e\\u0440\\u044f\\u0434\\u043a\\u0430 KB\\u2013MB (obs 18\\u00d73\\u00d71024 float32 \\u2248 0.2 MB), RAM 2 \\u0422\\u0411 \\u2014 \\u043f\\u043e\\u0442\\u043e\\u043b\\u043e\\u043a \\u043d\\u0435 \\u043f\\u0430\\u043c\\u044f\\u0442\\u044c. \\u041a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0439 \\u043f\\u043b\\u0430\\u0442\\u043e: \\u043f\\u0440\\u0438 \\u0443\\u0434\\u0432\\u043e\\u0435\\u043d\\u0438\\u0438 n_envs \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 steps/sec < 10% \\u2192 \\u043f\\u043b\\u0430\\u0442\\u043e \\u0434\\u043e\\u0441\\u0442\\u0438\\u0433\\u043d\\u0443\\u0442o; \\u043a\\u0440\\u0438\\u0432\\u0430\\u044f \\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u0443\\u0435\\u0442\\u0441\\u044f \\u0446\\u0435\\u043b\\u0438\\u043a\\u043e\\u043c.\\n\\n## (\\u0432) \\u0420\\u0443\\u043a\\u0438 \\u0438 \\u043c\\u0430\\u0442\\u0440\\u0438\\u0446\\u0430\\n\\n- **A(st=1)** \\u2014 JaxMARL MPEEnv, `OMP_NUM_THREADS=1`, XLA cpu pool=1; n_envs \\u2208 {1,16,64,256,1024}\\n- **A(mt=16)** \\u2014 \\u0442\\u043e \\u0436\\u0435, \\u0442\\u0440\\u0435\\u0434\\u043e\\u0432 16; \\u0442\\u0435 \\u0436\\u0435 n_envs\\n- **A(mt=64)** \\u2014 \\u0442\\u043e \\u0436\\u0435, \\u0442\\u0440\\u0435\\u0434\\u043e\\u0432 64; \\u0442\\u0435 \\u0436\\u0435 n_envs\\n- **B1** \\u2014 PettingZoo simple_spread_v3, \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e, 1 \\u044f\\u0434\\u0440\\u043e (\\u044d\\u0442\\u043e \\u0438 \\u0435\\u0441\\u0442\\u044c \\u00ab\\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 CPU-\\u0430\\u043d\\u0430\\u043b\\u043e\\u0433 \\u043e\\u0434\\u0438\\u043d-\\u043a-\\u043e\\u0434\\u043d\\u043e\\u043c\\u0443\\u00bb; n_envs \\u0437\\u0434\\u0435\\u0441\\u044c \\u043f\\u043e \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u044e 1)\\n- **B2(K\\u2208{16,64})** \\u2014 **\\u043e\\u0431\\u044f\\u0437\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u0430\\u044f** \\u0432\\u0435\\u0442\\u043a\\u0430: K \\u043d\\u0435\\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u044b\\u0445 \\u043f\\u0440\\u043e\\u0446\\u0435\\u0441\\u0441\\u043e\\u0432 (multiprocessing), \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 \\u043a\\u0440\\u0443\\u0442\\u0438\\u0442 \\u0441\\u0432\\u043e\\u0439 env \\u0431\\u0435\\u0437 IPC \\u043d\\u0430 \\u0448\\u0430\\u0433, \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u044f \\u0438\\u0442\\u043e\\u0433\\u043e\\u0432 \\u0432 \\u043a\\u043e\\u043d\\u0446\\u0435; K \\u043f\\u0440\\u043e\\u0446\\u0435\\u0441\\u0441\\u043e\\u0432 \\u0437\\u0430\\u043a\\u0440\\u0435\\u043f\\u043b\\u0435\\u043d\\u044b \\u043d\\u0430 \\u0442\\u043e\\u0442 \\u0436\\u0435 \\u043d\\u0430\\u0431\\u043e\\u0440 \\u0444\\u0438\\u0437\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0445 \\u044f\\u0434\\u0435\\u0440, \\u0447\\u0442\\u043e \\u0438 A(mt=K).\\n\\n\\u0412 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0435 \\u0438\\u0442\\u043e\\u0433\\u043e\\u0432\\u043e\\u0439 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u044b \\u2014 \\u043a\\u043e\\u043b\\u043e\\u043d\\u043a\\u0430 \\u00abphysical cores consumed (measured)\\u00bb. \\u0414\\u043b\\u044f A(mt) \\u0444\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u043f\\u043e\\u0442\\u0440\\u0435\\u0431\\u043b\\u0435\\u043d\\u0438\\u0435 \\u2264 K \\u0438 \\u044f\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u0447\\u0430\\u0441\\u0442\\u044c\\u044e \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u0430 (\\u044d\\u0442\\u043e \\u0436\\u0435 \\u0437\\u0430\\u043a\\u0440\\u044b\\u0432\\u0430\\u0435\\u0442 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441 \\u043c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u0438\\u0440\\u0443\\u0435\\u043c\\u043e\\u0441\\u0442\\u0438 XLA CPU: \\u043a\\u0440\\u0438\\u0432\\u0430\\u044f A \\u043f\\u043e n_envs \\u00d7 threads \\u2014 \\u0441\\u0430\\u043c\\u043e\\u0441\\u0442\\u043e\\u044f\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442).\\n\\n\\u0418\\u0442\\u043e\\u0433\\u043e \\u0441\\u0435\\u0442\\u043a\\u0430: A \\u2014 15 \\u044f\\u0447\\u0435\\u0435\\u043a \\u00d7 3 \\u0442\\u0440\\u0435\\u0434\\u0430 \\u00d7 7 \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440\\u043e\\u0432; B1 \\u2014 7 \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440\\u043e\\u0432; B2 \\u2014 2 \\u00d7 7.\\n\\n## (\\u0433) \\u041f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\n\\n**0. Provisioning (\\u043d\\u044b\\u043d\\u0435\\u0448\\u043d\\u0438\\u0439 \\u0431\\u043b\\u043e\\u043a\\u0435\\u0440 \\u2014 \\u0447\\u0435\\u0441\\u0442\\u043d\\u043e):** \\u0432 \\u0442\\u0435\\u043a\\u0443\\u0449\\u0435\\u043c \\u0440\\u0430\\u043d\\u0442\\u0430\\u0439\\u043c\\u0435 \\u043d\\u0435\\u0442 jax, jaxlib, numpy, pettingzoo, JaxMARL, \\u0438 **\\u0441\\u0435\\u0442\\u044c \\u043e\\u0442\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0430** \\u2192 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u0435\\u043d. \\u0422\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442\\u0441\\u044f: \\u0441\\u0435\\u0442\\u044c \\u0438\\u043b\\u0438 \\u0432\\u0435\\u043d\\u0434\\u043e\\u0440\\u0435\\u043d\\u043d\\u044b\\u0435 wheels; \\u043a\\u043b\\u043e\\u043d JaxMARL (git 2.53 \\u0435\\u0441\\u0442\\u044c) \\u043d\\u0430 pinned-\\u043a\\u043e\\u043c\\u043c\\u0438\\u0442; `pip install -e .`, `pettingzoo[mpe]`. **\\u0420\\u0438\\u0441\\u043a \\u0438\\u043d\\u0442\\u0435\\u0440\\u043f\\u0440\\u0435\\u0442\\u0430\\u0442\\u043e\\u0440\\u0430:** \\u0435\\u0434\\u0438\\u043d\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 Python \\u2014 3.14; \\u043a\\u043e\\u0440\\u0438\\u0434\\u043e\\u0440 wheels jax/jaxlib \\u043e\\u0431\\u044b\\u0447\\u043d\\u043e 3.10\\u20133.12, cp314-\\u0443\\u0430\\u0439\\u043b\\u043e\\u0432 \\u043c\\u043e\\u0436\\u0435\\u0442 \\u043d\\u0435 \\u0441\\u0443\\u0449\\u0435\\u0441\\u0442\\u0432\\u043e\\u0432\\u0430\\u0442\\u044c \\u2192 \\u043d\\u0443\\u0436\\u0435\\u043d \\u0432\\u0435\\u043d\\u0434\\u043e\\u0440\\u0435\\u043d\\u043d\\u044b\\u0439 CPython 3.11 \\u0432 \\u0434\\u043e\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u043a \\u0441\\u0435\\u0442\\u0438. \\u041f\\u0435\\u0440\\u0435\\u0434 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u043e\\u043c: `python -c \\\"import jax; print(jax.devices())\\\"` \\u2192 \\u043e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c CPU0 \\u043a\\u0430\\u043a sanity-check.\\n\\n**1. \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0441\\u0440\\u0435\\u0434\\u044b:** \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 timed-\\u043f\\u0440\\u043e\\u0446\\u0435\\u0441\\u0441 \\u043f\\u043e\\u0434 `taskset` (\\u0435\\u0441\\u0442\\u044c, util-linux 2.41) \\u043d\\u0430 \\u0437\\u0430\\u0440\\u0430\\u043d\\u0435\\u0435 \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u043d\\u0430\\u0431\\u043e\\u0440 \\u044f\\u0434\\u0435\\u0440; topology (`lscpu -p`) \\u0436\\u0443\\u0440\\u043d\\u0430\\u043b\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0434\\u043e \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u043e\\u0432 (\\u043c\\u043e\\u0439 \\u0447\\u0435\\u043a \\u043d\\u0435 \\u0432\\u0435\\u0440\\u043d\\u0443\\u043b \\u0441\\u0442\\u0440\\u043e\\u043a \\u2014 \\u0440\\u0435\\u0437\\u043e\\u043b\\u0432\\u0438\\u043c \\u0432 \\u0440\\u0430\\u043d \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u0430). Governor \\u0432 \\u044d\\u0442\\u043e\\u0439 \\u0432\\u0438\\u0440\\u0442\\u0443\\u0430\\u043b\\u043a\\u0435 \\u043d\\u0435 \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u0435\\u043d (`/sys/.../scaling_governor` \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442) \\u2014 \\u0432\\u043c\\u0435\\u0441\\u0442\\u043e \\u044d\\u0442\\u043e\\u0433\\u043e \\u043b\\u043e\\u0433\\u0438\\u0440\\u0443\\u0435\\u043c `/proc/loadavg` \\u0434\\u043e/\\u043f\\u043e\\u0441\\u043b\\u0435 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440\\u0430 \\u0438 \\u043e\\u0442\\u0431\\u0440\\u0430\\u0441\\u044b\\u0432\\u0430\\u0435\\u043c \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440 \\u043f\\u0440\\u0438 load > 0.5\\u00d7K \\u0441\\u0432\\u0435\\u0440\\u0445 \\u043e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c\\u043e\\u0433\\u043e. \\u0416\\u0443\\u0440\\u043d\\u0430\\u043b \\u043d\\u0430 \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d: \\u043a\\u043e\\u043c\\u043c\\u0438\\u0442 JaxMARL, \\u0432\\u0435\\u0440\\u0441\\u0438\\u0438 jax/jaxlib/numpy/pettingzoo, affinity mask, thread-\\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u044b\\u0435, loadavg.\\n\\n**2. Warmup/compile:** \\u0432\\u0440\\u0435\\u043c\\u044f \\u043f\\u0435\\u0440\\u0432\\u044b\\u0445 jit-\\u043a\\u043e\\u043c\\u043f\\u0438\\u043b\\u0438\\u0440\\u0443\\u044e\\u0449\\u0438\\u0445 \\u0432\\u044b\\u0437\\u043e\\u0432\\u043e\\u0432 A \\u0437\\u0430\\u043c\\u0435\\u0440\\u044f\\u0435\\u0442\\u0441\\u044f **\\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e\\u0439 \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u043e\\u0439** (compile time) \\u0438 \\u0432 steady-state \\u043d\\u0435 \\u0432\\u0445\\u043e\\u0434\\u0438\\u0442; \\u043f\\u043e\\u0441\\u043b\\u0435 \\u043a\\u043e\\u043c\\u043f\\u0438\\u043b\\u044f\\u0446\\u0438\\u0438 \\u2014 20 \\u043f\\u0440\\u043e\\u0433\\u0440\\u0435\\u0432\\u043e\\u0447\\u043d\\u044b\\u0445 \\u0432\\u044b\\u0437\\u043e\\u0432\\u043e\\u0432, \\u0437\\u0430\\u0442\\u0435\\u043c \\u0438\\u0437\\u043c\\u0435\\u0440\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0430 1000 \\u0432\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\\u0437\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0445 \\u0432\\u044b\\u0437\\u043e\\u0432\\u0430\\u0445 \\u0438\\u043b\\u0438 10 s wall-clock (\\u0447\\u0442\\u043e \\u0440\\u0430\\u043d\\u044c\\u0448\\u0435). B-\\u0440\\u0443\\u043a\\u0438: \\u0442\\u0435 \\u0436\\u0435 20/1000 \\u0432\\u044b\\u0437\\u043e\\u0432\\u043e\\u0432 \\u0431\\u0435\\u0437 \\u043a\\u043e\\u043c\\u043f\\u0438\\u043b\\u044f\\u0446\\u0438\\u0438.\\n\\n**3. \\u041f\\u043e\\u0432\\u0442\\u043e\\u0440\\u044b \\u0438 \\u043f\\u043e\\u0440\\u044f\\u0434\\u043e\\u043a:** 7 \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440\\u043e\\u0432 \\u043d\\u0430 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0443; \\u043f\\u043e\\u0440\\u044f\\u0434\\u043e\\u043a \\u0440\\u0443\\u043a \\u0432\\u043d\\u0443\\u0442\\u0440\\u0438 \\u0431\\u043b\\u043e\\u043a\\u0430 \\u0447\\u0435\\u0440\\u0435\\u0434\\u0443\\u0435\\u0442\\u0441\\u044f (\\u043b\\u0430\\u0442\\u0438\\u043d\\u0441\\u043a\\u0438\\u0439 \\u043a\\u0432\\u0430\\u0434\\u0440\\u0430\\u0442/\\u0440\\u0430\\u043d\\u0434\\u043e\\u043c \\u0441 fixed seed), \\u0447\\u0442\\u043e\\u0431\\u044b \\u0434\\u0440\\u0435\\u0439\\u0444 \\u043c\\u0430\\u0448\\u0438\\u043d\\u044b \\u043d\\u0435 \\u043f\\u0440\\u0438\\u043f\\u0438\\u0441\\u0430\\u043b\\u0441\\u044f \\u0440\\u0443\\u043a\\u0435.\\n\\n**4. \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c autoreset-\\u0441\\u043c\\u0435\\u0449\\u0435\\u043d\\u0438\\u044f:** autoreset \\u0443 A \\u043f\\u0440\\u043e\\u0438\\u0441\\u0445\\u043e\\u0434\\u0438\\u0442 **\\u0432\\u043d\\u0443\\u0442\\u0440\\u0438** timed step (\\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0430\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u0441\\u043c\\u0435\\u0449\\u0435\\u043d\\u0438\\u0435 **\\u0432 \\u043f\\u043e\\u043b\\u044c\\u0437\\u0443 A**? \\u2014 \\u043d\\u0430\\u043e\\u0431\\u043e\\u0440\\u043e\\u0442: \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430 \\u0440\\u0435\\u0441\\u0435\\u0442\\u0430 \\u0432\\u0445\\u043e\\u0434\\u0438\\u0442 \\u0432\\u043e \\u0432\\u0440\\u0435\\u043c\\u044f A, \\u0442.\\u0435. \\u0441\\u043c\\u0435\\u0449\\u0435\\u043d\\u0438\\u0435 \\u043f\\u0440\\u043e\\u0442\\u0438\\u0432 A \\u043d\\u0430 \\u043a\\u043e\\u0440\\u043e\\u0442\\u043a\\u0438\\u0445 \\u0433\\u043e\\u0440\\u0438\\u0437\\u043e\\u043d\\u0442\\u0430\\u0445; \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u043c \\u043d\\u0430\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u044f\\u0432\\u043d\\u043e). \\u0421\\u0435\\u0433\\u043c\\u0435\\u043d\\u0442\\u0430\\u0446\\u0438\\u044f \\u0437\\u0430\\u043c\\u0435\\u0440\\u0430: (i) H=100 \\u0448\\u0442\\u0430\\u0442\\u043d\\u044b\\u0439; (ii) H, \\u0437\\u0430\\u0433\\u043b\\u0443\\u0448\\u0451\\u043d\\u043d\\u044b\\u0439 \\u0431\\u043e\\u043b\\u044c\\u0448\\u0438\\u043c (\\u0435\\u0441\\u043b\\u0438 env \\u043f\\u043e\\u0437\\u0432\\u043e\\u043b\\u044f\\u0435\\u0442 \\u0437\\u0430\\u0434\\u0430\\u0442\\u044c horizon \\u2014 \\u0441\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043f\\u043e \\u043a\\u043e\\u0434\\u0443), \\u0431\\u0435\\u0437 \\u0440\\u0435\\u0441\\u0435\\u0442\\u043e\\u0432 \\u0432 \\u043e\\u043a\\u043d\\u0435 \\u0437\\u0430\\u043c\\u0435\\u0440\\u0430; \\u0440\\u0430\\u0437\\u043d\\u0438\\u0446\\u0430 \\u043f\\u043e \\u0440\\u0443\\u043a\\u0430\\u043c = \\u0432\\u043a\\u043b\\u0430\\u0434 autoreset \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0440\\u043e\\u043a\\u043e\\u0439. \\u0415\\u0441\\u043b\\u0438 \\u0437\\u0430\\u0433\\u043b\\u0443\\u0448\\u0438\\u0442\\u044c \\u043d\\u0435\\u043b\\u044c\\u0437\\u044f \\u2014 \\u0441\\u0442\\u0440\\u043e\\u043a\\u0430 \\u00ab\\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u043d\\u043e\\u0435 \\u0441\\u043c\\u0435\\u0449\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0430\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f: A \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u0442 autoreset \\u0432 step-\\u0432\\u0440\\u0435\\u043c\\u044f, B \\u043d\\u0435 \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u0442 reset \\u0432\\u043e\\u0432\\u0441\\u0435\\u00bb. \\u042d\\u043a\\u0441\\u043f\\u043e\\u0440\\u0442/\\u0440\\u0435\\u043d\\u0434\\u0435\\u0440/\\u043f\\u0430\\u0440\\u0441\\u0438\\u043d\\u0433/\\u0441\\u043e\\u0437\\u0434\\u0430\\u043d\\u0438\\u0435 env/import \\u2014 \\u0432\\u043d\\u0435 \\u0432\\u0441\\u0435\\u0445 \\u0442\\u0430\\u0439\\u043c\\u0435\\u0440\\u043e\\u0432.\\n\\n## (\\u0434) \\u0410\\u043d\\u0430\\u043b\\u0438\\u0437\\n\\n- \\u041f\\u043e \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0435: **\\u043c\\u0435\\u0434\\u0438\\u0430\\u043d\\u0430 + IQR \\u043f\\u043e 7 \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440\\u0430\\u043c** (\\u043d\\u0435 \\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u0435); \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u043e \\u043e\\u0442\\u0431\\u0440\\u0430\\u043a\\u043e\\u0432\\u043a\\u0438: \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440 \\u0441 loadavg-\\u0430\\u043d\\u043e\\u043c\\u0430\\u043b\\u0438\\u0435\\u0439 \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u0442\\u0441\\u044f \\u0438 \\u0434\\u043e\\u0431\\u0438\\u0440\\u0430\\u0435\\u0442\\u0441\\u044f.\\n- **Per-core \\u043d\\u043e\\u0440\\u043c\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f**: steps/sec \\u00f7 \\u0438\\u0437\\u043c\\u0435\\u0440\\u0435\\u043d\\u043d\\u044b\\u0435 \\u044f\\u0434\\u0440\\u0430 \\u2014 \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445 A/B1/B2.\\n- **\\u041a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0439 \\u043f\\u043b\\u0430\\u0442\\u043e** \\u043f\\u043e n_envs: \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 < 10% \\u043f\\u0440\\u0438 \\u0443\\u0434\\u0432\\u043e\\u0435\\u043d\\u0438\\u0438 \\u2192 \\u043f\\u043b\\u0430\\u0442\\u043e; \\u0442\\u043e\\u0447\\u043a\\u0430 \\u043f\\u043e\\u043b\\u0443\\u043f\\u043b\\u0430\\u0442\\u043e (\\u043f\\u0435\\u0440\\u0432\\u044b\\u0439 n_envs \\u0441 \\u226550% \\u043d\\u0430\\u043a\\u043b\\u043e\\u043da asymptote) \\u043a\\u0430\\u043a \\u043e\\u043f\\u0438\\u0441\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u0430\\u044f \\u0445\\u0430\\u0440\\u0430\\u043a\\u0442\\u0435\\u0440\\u0438\\u0441\\u0442\\u0438\\u043a\\u0430.\\n- **\\u041e\\u0442\\u0432\\u0435\\u0442 \\u043d\\u0430 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441** = \\u0434\\u0432\\u0430 \\u0447\\u0438\\u0441\\u043b\\u0430: (1) \\u043e\\u0442\\u043d\\u043e\\u0448\\u0435\\u043d\\u0438\\u0435 A(mt=K)/B2(K) **\\u043f\\u0440\\u0438 \\u0440\\u0430\\u0432\\u043d\\u043e\\u043c \\u0447\\u0438\\u0441\\u043b\\u0435 \\u044f\\u0434\\u0435\\u0440**, \\u043f\\u043e \\u0442\\u0440\\u0451\\u043c \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430\\u043c; (2) \\u043e\\u0442\\u043d\\u043e\\u0448\\u0435\\u043d\\u0438\\u0435 A(st=1)/B1 \\u043f\\u0440\\u0438 wall-clock \\u00ab\\u043e\\u0434\\u0438\\u043d-\\u043a-\\u043e\\u0434\\u043d\\u043e\\u043c\\u0443\\u00bb; \\u043f\\u043b\\u044e\\u0441 \\u043a\\u0440\\u0438\\u0432\\u0430\\u044f A(mt) n_envs \\u00d7 threads \\u043a\\u0430\\u043a \\u0440\\u0430\\u0437\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435 \\u00ab\\u0432\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f vs \\u044f\\u0434\\u0440\\u0430\\u00bb. \\u041d\\u0438\\u043a\\u0430\\u043a\\u0438\\u0445 \\u0430\\u043f\\u0440\\u0438\\u043e\\u0440\\u043d\\u044b\\u0445 \\u043e\\u0436\\u0438\\u0434\\u0430\\u043d\\u0438\\u0439 \\u0432\\u0435\\u043b\\u0438\\u0447\\u0438\\u043d\\u044b \\u043e\\u0442\\u043d\\u043e\\u0448\\u0435\\u043d\\u0438\\u044f \\u043d\\u0435 \\u0437\\u0430\\u043a\\u043b\\u0430\\u0434\\u044b\\u0432\\u0430\\u0435\\u043c.\\n\\n## (\\u0435) \\u041e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u044f \\u0438 \\u0432\\u0430\\u043b\\u0438\\u0434\\u043d\\u043e\\u0441\\u0442\\u044c\\n\\n1. **GPU \\u043d\\u0435\\u0442** (\\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u043e \\u0440\\u0430\\u043d\\u0442\\u0430\\u0439\\u043c\\u043e\\u043c) \\u2192 \\u00abGPU-\\u0443\\u0441\\u043a\\u043e\\u0440\\u0435\\u043d\\u043d\\u044b\\u0439 JaxMARL\\u00bb \\u043d\\u0435\\u0438\\u0437\\u043c\\u0435\\u0440\\u0438\\u043c; \\u0432\\u0441\\u0435 JAX-\\u0446\\u0438\\u0444\\u0440\\u044b \\u2014 CPU-backend XLA. \\u041e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430.\\n2. **\\u0414\\u0438\\u0437\\u0430\\u0439\\u043d, \\u043d\\u0435 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0434\\u0451\\u043d**: \\u0432 \\u0442\\u0435\\u043a\\u0443\\u0449\\u0435\\u043c \\u0440\\u0430\\u043d\\u0442\\u0430\\u0439\\u043c\\u0435 \\u043d\\u0435 \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0438\\u043c\\u043e \\u043d\\u0438\\u0447\\u0435\\u0433\\u043e, \\u043a\\u0440\\u043e\\u043c\\u0435 \\u043d\\u0430\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u044f \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u0430 (\\u043d\\u0435\\u0442 \\u043f\\u0430\\u043a\\u0435\\u0442\\u043e\\u0432, \\u043d\\u0435\\u0442 \\u0441\\u0435\\u0442\\u0438, \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e Python 3.14 \\u0432\\u043d\\u0435 \\u043a\\u043e\\u0440\\u0438\\u0434\\u043e\\u0440\\u0430 jax). \\u0414\\u043b\\u044f \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u0430 \\u043d\\u0443\\u0436\\u043d\\u044b: \\u0441\\u0435\\u0442\\u044c/wheels, CPython 3.10\\u20133.12, \\u043a\\u043b\\u043e\\u043d JaxMARL, PettingZoo[mpe].\\n3. \\u041b\\u043e\\u043a\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u0438\\u043a\\u043e\\u0432 \\u043d\\u0435\\u0442 \\u2192 \\u0432\\u0441\\u044f \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430 (\\u0431) \\u043f\\u043e\\u043c\\u0435\\u0447\\u0435\\u043d\\u0430 \\u00ab\\u0441\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c\\u00bb; \\u0434\\u0438\\u0441\\u043a\\u0440\\u0435\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c \\u0434\\u0435\\u0439\\u0441\\u0442\\u0432\\u0438\\u0439 \\u043d\\u0435 \\u043f\\u0440\\u043e\\u0434\\u0430\\u0451\\u043c \\u043a\\u0430\\u043a \\u0444\\u0430\\u043a\\u0442.\\n4. Autoreset-\\u0441\\u043c\\u0435\\u0449\\u0435\\u043d\\u0438\\u0435 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0441\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u0435\\u043c (ii) \\u043b\\u0438\\u0431\\u043e \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a \\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u043d\\u043e\\u0435.\\n5. B2 \\u2014 \\u0447\\u0435\\u0441\\u0442\\u043d\\u044b\\u0439 CPU-\\u043f\\u0430\\u0440\\u0430\\u043b\\u043b\\u0435\\u043b\\u0438\\u0437\\u043c, \\u043d\\u043e \\u043d\\u0435 \\u0438\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u0435\\u043d \\u043f\\u043e \\u043d\\u0430\\u043a\\u043b\\u0430\\u0434\\u043d\\u044b\\u043c (Python-\\u043f\\u0440\\u043e\\u0446\\u0435\\u0441\\u0441\\u044b vs \\u043e\\u0434\\u0438\\u043d JAX-\\u043f\\u0440\\u043e\\u0446\\u0435\\u0441\\u0441) \\u2014 \\u043d\\u0430 \\u0442\\u043e \\u0438 \\u0435\\u0441\\u0442\\u044c per-core \\u0441\\u0442\\u043e\\u043b\\u0431\\u0435\\u0446 \\u0438 B1.\\n\\n### Feedback \\u043f\\u043e feasibility (\\u0440\\u0435\\u0437\\u044e\\u043c\\u0435)\\n\\u0412\\u044b\\u043f\\u043e\\u043b\\u043d\\u0438\\u043c\\u043e \\u0441\\u0435\\u0439\\u0447\\u0430\\u0441: \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u044d\\u0442\\u043e\\u0442 \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442. \\u0414\\u043b\\u044f \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u0430: (1) \\u0441\\u0435\\u0442\\u044c \\u0438\\u043b\\u0438 \\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u044b (wheels + tarball CPython 3.11), (2) \\u0440\\u0435\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0438\\u0438 JaxMARL \\u0438 PettingZoo, (3) \\u0432\\u0441\\u0451 \\u043e\\u0441\\u0442\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435 \\u0443\\u0436\\u0435 \\u0435\\u0441\\u0442\\u044c: 224-\\u044f\\u0434\\u0435\\u0440\\u043d\\u0430\\u044f \\u043c\\u0430\\u0448\\u0438\\u043d\\u0430, taskset, git, ~2 \\u0422\\u0411 RAM, \\u0438\\u0437\\u0431\\u044b\\u0442\\u043e\\u0447\\u043d\\u044b\\u0445 \\u044f\\u0434\\u0435\\u0440 K\\u226464 \\u2014 \\u0441 \\u0437\\u0430\\u043f\\u0430\\u0441\\u043e\\u043c.\", \"evidence\": \"\\u0418\\u043d\\u0441\\u043f\\u0435\\u043a\\u0446\\u0438\\u0438: /workspace \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u0442 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e task.json; jax/jaxlib/gymnax/pettingzoo/mpe/gym/numpy \\u2014 ModuleNotFoundError; \\u0441\\u0435\\u0442\\u044c \\u043e\\u0442\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0430; /usr/bin \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e python3.14 (\\u0430\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u044b\\u0445 \\u0438\\u043d\\u0442\\u0435\\u0440\\u043f\\u0440\\u0435\\u0442\\u0430\\u0442\\u043e\\u0440\\u043e\\u0432 \\u043d\\u0435\\u0442); taskset 2.41.3 \\u0438 git 2.53 \\u043f\\u0440\\u0438\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442; GPU-\\u0443\\u0441\\u0442\\u0440\\u043e\\u0439\\u0441\\u0442\\u0432 \\u043d\\u0435\\u0442 (/dev/nvidia*, /dev/dri \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442); os.cpu_count()=224, affinity 0\\u2013223, Intel Xeon Platinum 8570, RAM ~2 \\u0422\\u0411; scaling_governor \\u0432 /sys \\u043d\\u0435\\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u0435\\u043d, `lscpu -p=CORE,SOCKET` \\u0432 \\u043c\\u043e\\u0451\\u043c \\u0447\\u0435\\u043a\\u0435 \\u0441\\u0442\\u0440\\u043e\\u043a \\u043d\\u0435 \\u0432\\u0435\\u0440\\u043d\\u0443\\u043b (\\u0442\\u043e\\u043f\\u043e\\u043b\\u043e\\u0433\\u0438\\u044e \\u0440\\u0435\\u0437\\u043e\\u043b\\u0432\\u0438\\u0442\\u044c \\u0432 \\u0440\\u0430\\u043d \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u0430). \\u041a\\u043e\\u043d\\u0444\\u0438\\u0433 Simple Spread (3 \\u0430\\u0433\\u0435\\u043d\\u0442\\u0430, 2 \\u043b\\u0435\\u043d\\u0434